messages.content:
{
  "explanation": "I can help you get service back. We’ll do two things in parallel: (1) run quick checks on your phone that commonly fix ‘No Service’, and (2) verify your line status on our side (e.g., suspension or SIM/activation issues).",
  "request_for_identification": {
    "prompt": "To check your line, please provide one of the following:",
    "options": [
      "The phone number of the affected line (preferred)",
      "Your customer ID",
      "Your full name and date of birth (YYYY-MM-DD)"
    ]
  },
  "quick_checks_on_phone": {
    "why": "‘No Service’ is often caused by Airplane Mode, a SIM seating issue, or a temporary network registration glitch.",
    "steps": [
      {
        "step": "Check Airplane Mode",
        "instructions": "Look at the status bar. If you see an airplane icon, turn Airplane Mode OFF. If it’s already off, toggle it ON, wait 10 seconds, then turn it OFF again.",
        "result_to_share": "Tell me if the signal bars reappear after this."
      },
      {
        "step": "Reboot the phone",
        "instructions": "Restart your phone normally. After it powers back on, wait 1–2 minutes and check if service returns.",
        "result_to_share": "Let me know if it still shows ‘No Service’."
      },
      {
        "step": "Reseat the SIM (skip if eSIM-only)",
        "instructions": "Power the phone off, remove the SIM tray, reinsert the SIM firmly, and power back on.",
        "result_to_share": "Tell me if the network appears after the SIM is reseated."
      }
    ]
  },
  "additional_questions": [
    "Are you currently traveling outside your usual area or internationally?",
    "Is your device using a physical SIM or eSIM?",
    "What phone model are you using?",
    "Did anything change recently (new phone/SIM, port-in, plan change, or any account changes)?",
    "Have you already tried any steps? If so, which ones and what happened?"
  ],
  "next_step_after_you_reply": "Once I have your line details and the results of the quick checks, I’ll look up your account, confirm the line status, and take the appropriate steps to restore service."
}

