{
  "thought_process": "I located your account and verified the affected line’s status on our side first. Your account is Active, and your line ending in 2002 (Line ID L1002) is Active with roaming enabled and no suspensions or contract issues. Since nothing on the account side would block service, the ‘No Service’ is likely due to a device-side network registration or SIM issue. I’ll guide you through quick diagnostics and fixes in order of fastest impact.",
  "account_summary": {
    "customer_id": "C1001",
    "line_id": "L1002",
    "phone_number": "555-123-2002",
    "line_status": "Active",
    "roaming_enabled": true,
    "notes": "No overdue/suspension flags; last SIM replacement 2025-01-20."
  },
  "plan_of_action": [
    {
      "step": 1,
      "goal": "Collect key diagnostics to pinpoint the cause",
      "instructions": [
        {
          "ask": "On the affected phone, run check_network_status and share the full results.",
          "why": "Confirms airplane mode, signal strength, network type, mobile data, and roaming state.",
          "what_to_share": "Airplane mode status, signal strength, network type (e.g., 5G/4G/3G/none), mobile data ON/OFF, roaming ON/OFF."
        },
        {
          "ask": "Run check_sim_status and share the result.",
          "why": "Tells us if the SIM is Active, Missing, or Locked.",
          "what_to_share": "Exact SIM status text. If it says Locked (PIN/PUK), tell me immediately so I can transfer you for SIM security assistance."
        }
      ]
    },
    {
      "step": 2,
      "goal": "Force a quick network re-registration",
      "instructions": [
        {
          "ask": "Toggle Airplane Mode ON for 10 seconds, then OFF using toggle_airplane_mode.",
          "why": "Resets all radios and often restores service after local network glitches.",
          "after": "Wait ~30–60 seconds and check if bars return or if ‘No Service’ changes."
        }
      ]
    },
    {
      "step": 3,
      "goal": "Ensure proper SIM contact",
      "instructions": [
        {
          "ask": "If still ‘No Service’, reseat the SIM using reseat_sim_card.",
          "why": "Corrects issues from minor SIM contact problems.",
          "after": "After reseating, wait ~30–60 seconds and see if service returns."
        }
      ],
      "skip_if": "check_sim_status reported Locked (we’ll handle that separately) or Missing (reseat is still appropriate)."
    },
    {
      "step": 4,
      "goal": "Confirm optimal network mode",
      "instructions": [
        {
          "ask": "Run check_network_mode_preference and share the result.",
          "why": "Old modes (2G/3G) can prevent proper registration.",
          "then": "If it shows 2G/3G only, set to 4g_5g_preferred using set_network_mode_preference, then wait ~30 seconds."
        }
      ]
    },
    {
      "step": 5,
      "goal": "Refresh all radio/services",
      "instructions": [
        {
          "ask": "Reboot the device using reboot_device.",
          "why": "Clears temporary glitches after changes above.",
          "after": "Check if service is restored post-reboot."
        }
      ]
    },
    {
      "step": 6,
      "goal": "Optional temporary workaround (if you need to place calls now and have Wi‑Fi)",
      "instructions": [
        {
          "ask": "If you have Wi‑Fi available, enable Wi‑Fi Calling using toggle_wifi_calling.",
          "why": "Lets you make/receive calls over Wi‑Fi while we finish troubleshooting cellular service."
        }
      ]
    }
  ],
  "what_i_need_from_you_now": [
    "Please run: check_network_status and check_sim_status, then paste both results here.",
    "After that, go ahead with Step 2 (airplane mode toggle) and tell me if service returns.",
    "If it doesn’t, continue with Step 3 and Step 4, and let me know the outputs and whether anything changes."
  ],
  "notes_on_escalation": "If check_sim_status shows the SIM is Locked (PIN/PUK), I will transfer you to a human agent to assist with SIM security. Otherwise, I’ll continue helping you here until we restore service."
}

