      "step": "Reset APN to default (if still No Signal after step 2)",
      "why": "Incorrect APN can sometimes block registration/data. Resetting restores carrier defaults.",
      "how": [
        "Android: Settings > Network & Internet > Mobile network > Access Point Names > Menu > Reset to default.",
        "iPhone: Settings > General > Transfer or Reset > Reset > Reset Network Settings (note this also resets Wi‑Fi passwords)."
      ],
      "after": "Reboot the phone once more and check for signal bars."
    }
