    "The phone number of the line with the issue (so I can check your line status, data usage, and plan limits).",
    "Are you currently traveling outside your usual coverage area/country?"
  ],
  "quick_device_checks_first": [
    {
      "why": "Confirm you have service and that mobile data is actually on.",
      "do_this": "check_status_bar",
      "tell_me": "Do you see: any signal bars (📶¹/²/³/⁴), a network type (5G/4G/LTE/3G), and “📱 Data Enabled”? Make sure you do NOT see “✈️ Airplane Mode”."
    },
    {
      "why": "Verify data switch and network type from the phone’s view.",
      "do_this": "check_network_status",
      "tell_me": "What does it show for: signal strength, network type, Mobile Data (ON/OFF), and Data Roaming (ON/OFF)?"
    },
    {
      "why": "Measure actual speed (anything below “excellent” is considered slow for our checks).",
      "do_this": "run_speed_test",
      "tell_me": "What result do you get? (unknown/very poor/poor/fair/good/excellent)"
    }
  ],
  "if_something_is_off_toggle_these": [
    {
      "issue": "Mobile Data shows OFF",
      "fix": "toggle_data to turn it ON"
    },
    {
      "issue": "Data Saver is limiting speeds",
      "check": "check_data_restriction_status",
      "fix": "toggle_data_saver_mode to turn it OFF"
    },
    {
      "issue": "VPN may be slowing things down",
      "check": "check_vpn_status",
      "fix": "disconnect_vpn if it’s connected"
    },
    {
      "issue": "Phone locked to older networks",
      "check": "check_network_mode_preference",
      "fix": "set_network_mode_preference to \"4g_5g_preferred\" if it shows 2G/3G"
