  "what_i_see": "Your line is active and paid. The phone shows both “No Signal” (not registered on the network) and “Data Disabled” (mobile data switch is OFF). We’ll fix the data switch first, then address the lack of signal.",
  "steps_with_reasons": [
    {
      "step": "Turn Mobile Data ON",
      "why": "Removes the “Data Disabled” state and allows data once signal returns.",
      "android_instructions": "Swipe down for Quick Settings and tap Mobile Data so it’s ON. Or go to Settings > Network & Internet (or Connections) > SIMs/Mobile network > Mobile data and turn it ON.",
      "tell_me": "Does “Data Disabled” disappear?"
    },
    {
      "step": "Check SIM Status",
      "why": "If the SIM is missing or locked, the phone cannot connect to the network.",
      "android_instructions": "Go to Settings > About phone > SIM status (or Settings > Network & Internet > SIMs > select your SIM > Status).",
      "what_to_report": "Tell me exactly what it says for SIM status (e.g., Active/Connected, No SIM, SIM not provisioned, SIM locked/PIN/PUK, or No service)."
    },
    {
      "step": "Set Preferred Network Mode to 4G/5G",
      "why": "Ensures the phone can register on modern networks instead of being stuck on older modes.",
      "android_instructions": "Settings > Network & Internet (or Connections) > Mobile network > Preferred network type. Choose 5G/4G/LTE (often labeled 5G/4G/3G/2G Auto or 5G recommended).",
      "extra": "After changing, wait 30–60 seconds to allow re-registration."
    },
    {
      "step": "Reseat the SIM (if still no signal)",
      "why": "A slightly mis-seated SIM can cause ‘No Signal’.",
      "android_instructions": "Power the phone OFF. Remove the SIM tray, gently reinsert the SIM so it sits flat, then power ON. After boot, wait up to 1 minute for bars to appear.",
      "skip_if": "If your device uses eSIM only, let me know instead of reseating."
    }
  ],
  "branching_notes": [
    "If SIM status shows Locked (PIN/PUK), stop and tell me. I’ll transfer you to a specialist for SIM security.",
    "If signal bars appear at any point, try a test call and a quick web page with Wi‑Fi off."
  ],
  "please_reply_with": "1) Whether Mobile Data is now ON, 2) the exact SIM status text, 3) what Preferred network mode is set to, and 4) what you see after any SIM reseat. I’ll advise the next step based on your results."
}

