    {
      "title": "Test MMS",
      "how": "Send a small photo to your own number.",
      "why": "Quick functional check that MMS is passing."
    }
  ],
  "if_still_on_2g_or_mms_fails": [
    {
      "title": "Reset APN to default, then reboot",
      "how": "Settings > Mobile network/Connections > Access Point Names > Menu (⋮) > Reset to default. Then restart the phone.",
      "why": "Fixes incorrect MMSC/APN entries that commonly break MMS."
    },
    {
      "title": "Retest after reboot",
      "how": "Confirm LTE/4G/5G appears, browse a site, then send a small MMS to yourself.",
      "why": "Validates the fix."
