messages.content:
{
  "acknowledgement": "Great catch on the permissions—those are essential for MMS. Yes, let’s run a couple of quick send/receive tests to confirm everything is fully working.",
  "thought_process": "Your mobile data and network look excellent now. Since Messages was missing Storage and SMS permissions, that likely blocked MMS creation/sending. After granting them, a real-world send/receive test is the best confirmation.",
  "tests_to_run_now": [
    {
      "step": "Keep Wi‑Fi OFF for the test",
      "reason": "Ensures MMS uses mobile data (the standard path)."
    },
    {
      "step": "Send a small photo to your own number",
      "how": "Use a small image (ideally <500 KB). Note whether it shows ‘Sending…’ then ‘Sent’ and whether you receive it.",
      "reason": "Validates outbound and inbound MMS on your line."
    },
    {
      "step": "Send the same photo to another contact and ask them to reply with a photo",
      "reason": "Confirms MMS works to other numbers and inbound MMS back to you."
    },
    {
      "step": "Optional: Turn Wi‑Fi back ON (Wi‑Fi Calling still OFF) and repeat one send",
      "reason": "Many phones still use mobile data for MMS even with Wi‑Fi ON. This checks day‑to‑day behavior."
    }
  ],
  "if_any_test_fails": [
    {
      "step": "Reduce attachment size and retry",
      "reason": "Large files can fail depending on device/network conditions."
    },
    {
      "step": "Ensure background data for Messages is ON",
      "how": "Settings > Apps > Messages > Mobile data/Data usage > enable Background data (and ‘Allow while Data Saver is on’ if present)."
    },
    {
      "step": "Force stop Messages and clear cache (not data)",
      "how": "Settings > Apps > Messages > Force stop, then Storage > Clear cache.",
      "reason": "Resets the app’s MMS pipeline without removing your messages."
    },
    {
      "step": "Verify the active APN shows an MMSC value",
      "how": "Settings > Mobile network/Connections > Access Point Names > tap the active APN and confirm the MMSC field is populated (view only)."
    },
    {
      "step": "Reboot once more and retry the send",
      "reason": "Clears any lingering app/network state."
    }
  ],
  "request": "Please try sending the photo to yourself and to another contact now and let me know: 1) Do both sends show ‘Sent’? 2) Did you receive the MMS to yourself and the reply from your contact? 3) If any failed, what exact status/message did you see and after how long?"
}

