  "why_these_steps": [
    "Account check: If your line hit its data limit, is suspended, or roaming isn’t enabled while traveling, data can stop or slow.",
    "Phone check: Airplane mode, mobile data switch, VPN/Data Saver, or network mode can reduce speeds. A quick snapshot and a speed test tells us where the problem is."
  ],
  "what_i_need_from_you": {
    "identify_customer": "Please share one of the following so I can look up your line: your mobile phone number (preferred), your customer ID, or your full name and date of birth (YYYY-MM-DD).",
    "quick_questions": [
      "Are you currently traveling outside your usual area or internationally?",
      "What kind of phone do you have (Android or iPhone)?"
    ]
  },
  "on_your_phone_now": {
    "step_1_status_bar": "Please look at the top of your screen and tell me exactly what you see: signal bars (how many), network type (5G/4G/3G/2G), if you see an airplane ✈️, a data icon 📱, a Wi‑Fi icon 📡, or a VPN lock 🔒.",
    "step_2_speed_test": "Turn OFF Wi‑Fi temporarily so we test cellular only, then run a speed test and tell me the result rating (e.g., excellent/good/fair/poor/very poor or no connection). If you can’t find a speed test, just say so and I’ll guide you."
  },
  "notes": [
    "If Airplane mode is ON, we’ll turn it OFF.",
    "If Mobile Data is OFF, we’ll turn it ON.",
    "If Data Saver or a VPN is ON, we’ll turn them OFF for testing.",
    "If your phone prefers older networks (like 3G), we’ll switch it to 4G/5G preferred."
  ],
  "next": "Please reply with your phone number (or other ID option), your travel status, your phone type, the status bar details, and the speed test result. I’ll use that to run checks on your account and walk you through the exact fixes step by step."
}

