  "thought_process": "Since refueling, rebooting, and turning off Wi‑Fi Calling didn’t fix it, the next likely causes are network mode, Data Saver/background data, VPN interference, or APN/MMSC settings. We’ll go step-by-step and test after each change.",
  "quick_data_check": "Before changing settings, with Wi‑Fi OFF, can you open a browser and load a site like example.com over mobile data? This confirms general data is working.",
  "step_now": {
    "title": "Confirm Preferred Network Type is 4G/5G",
    "why": "Being stuck on 2G/3G can break MMS.",
    "how_android": [
      "Settings > Network & Internet (or Connections) > Mobile network (or SIMs).",
      "Preferred network type (or Network mode): select 5G/4G (LTE) preferred.",
      "Wait ~10 seconds, confirm you see 4G/LTE/5G in the status bar.",
      "With Wi‑Fi still OFF, try sending a small photo MMS again."
    ]
  },
  "if_still_not_working_next_steps": [
    {
      "title": "Turn OFF Data Saver and allow background data for Messages",
      "why": "Data Saver or restricted background data can block MMS transfers.",
      "how_android": [
        "Settings > Network & Internet (or Connections) > Data Saver: turn it OFF.",
        "Settings > Apps > Messages (your default messaging app) > Mobile data & Wi‑Fi (or Data usage).",
        "Turn ON ‘Allow background data’ and ‘Unrestricted data’ (if available).",
        "Test MMS again with Wi‑Fi OFF."
      ]
    },
    {
      "title": "Disconnect any VPN",
      "why": "VPNs can interfere with MMS routing.",
      "how_android": [
        "Settings > Network & Internet > VPN: disconnect, or open your VPN app and tap Disconnect.",
        "Test MMS again."
      ]
    },
    {
      "title": "Reset APN to default, then reboot",
      "why": "Incorrect APN/MMSC is a common MMS failure point; resetting restores the correct MMSC.",
      "how_android": [
        "Settings > Network & Internet (or Connections) > Mobile network > Access Point Names.",
        "Tap the menu (⋮) > Reset to default.",
        "Restart the phone.",
        "After it’s back on, keep Wi‑Fi OFF and test MMS again."
      ]
    },
    {
      "title": "Check Messages app permissions",
      "why": "MMS needs SMS and Storage/Photos permissions.",
      "how_android": [
        "Settings > Apps > Messages > Permissions.",
        "Ensure SMS and Photos and videos (or Storage) are Allowed.",
        "Test MMS again."
      ]
    }
  ],
  "questions": [
    "Please try the Network Mode step now and tell me if MMS sends.",
    "If it still fails, did the quick data check (browsing a website with Wi‑Fi OFF) work?",
    "Do you use a VPN on this phone?"
  ]
}

messages.content:
{
  "assessment": "MMS won’t work while your phone shows No Signal and Data Disabled. We need to restore cellular signal and turn mobile data ON before testing anything else.",
  "why": [
    "No Signal means the phone isn’t registered on the network, so calls/data/MMS can’t work.",
    "Data Disabled means the mobile data switch is OFF, which also blocks MMS."
  ],
  "do_first_now": [
    {
      "title": "Turn Mobile Data ON",
      "android_quick": [
        "Swipe down twice to open Quick Settings.",
        "Tap the Mobile data tile to turn it ON.",
        "Wait ~10–15 seconds and look for 4G/LTE/5G in the status bar."
      ],
      "android_settings": [
        "Settings > Network & Internet (or Connections) > SIMs/Mobile network.",
        "Turn Mobile data ON."
      ]
    },
    {
      "title": "Make sure Airplane Mode is OFF (then toggle it to refresh)",
      "android": [
        "Check Quick Settings: if you see an airplane icon lit, tap it to turn Airplane mode OFF.",
        "Even if it’s OFF, toggle it ON for 10 seconds, then OFF again to refresh the radio.",
        "Wait ~10 seconds and check if signal bars appear."
      ]
    },
    {
      "title": "Try a better reception spot",
      "android": [
        "If you’re indoors, move near a window or step outside for a moment.",
        "Watch the status bar for any signal bars or a network type (4G/LTE/5G)."
      ]
    }
  ],
  "if_no_signal_persists": [
    {
      "title": "Check SIM status",
      "why": "If the SIM isn’t detected or is locked, the phone can’t connect to the network.",
      "android": [
        "Settings > About phone (or Settings > Network & Internet > SIMs) > SIM status.",
        "Tell me what it shows: Active, Missing, or Locked."
      ]
    },
    {
      "title": "Reseat the SIM card",
      "why": "A slightly mis-seated SIM can cause ‘No Signal’.",
      "steps": [
        "Power OFF the phone.",
        "Remove the SIM tray with the eject tool or a paperclip.",
        "Gently remove and reinsert the SIM so it sits flat and snug.",
        "Reinsert the tray, then power ON.",
        "Wait 30–60 seconds for signal bars; ensure Mobile data is ON."
      ],
      "note": "If your device uses eSIM only, skip this step and just let me know."
    }
  ],
  "after_signal_is_back": [
    "With Wi‑Fi OFF and Mobile data ON, open a browser and load a simple site (e.g., example.com) to confirm data works.",
    "Then try sending an MMS again."
  ],
  "next_steps_if_needed": [
    "If data works but MMS still fails, we’ll reset APN to default and reboot to refresh the MMSC settings."
  ],
  "questions": [
    "Please turn Mobile data ON and toggle Airplane mode as above. Do you now see any signal bars or a 4G/LTE/5G indicator?",
    "If still No Signal, what does SIM status report (Active, Missing, or Locked)?"
  ]
}

