messages.content:
{
  "thought_process": "You now have strong 5G signal and roaming enabled, so MMS should work. If it doesn’t, the most common blockers are: (1) Wi‑Fi Calling interfering, (2) the Messages app missing storage/SMS permissions, or (3) an APN/MMSC setting needing a reset. We’ll go in that order. None of these steps will delete your photos.",
  "reassurance": "You will not lose any photos or personal files by changing these settings, turning Wi‑Fi Calling off, or resetting APN. We are not clearing app data.",
  "quick_check": [
    "With Wi‑Fi still OFF, please quickly open your web browser and load any website (e.g., example.com). If it loads, mobile data is working fine. If it doesn’t, tell me right away."
  ],
  "steps_now": [
    {
      "step": "Turn Wi‑Fi Calling OFF (just for testing)",
      "why": "Some carriers don’t support MMS over Wi‑Fi Calling, or it can conflict while roaming.",
      "android_paths": [
        "Samsung: Settings > Connections > Wi‑Fi Calling > OFF",
        "Google Pixel: Settings > Network & Internet > SIMs > Wi‑Fi Calling > OFF",
        "Others (Motorola/OnePlus/etc.): Settings > Network & Internet (or Connections) > Wi‑Fi Calling > OFF"
      ]
    },
    {
      "step": "Test MMS",
      "how": "Keep Wi‑Fi OFF. Open Messages and send a small photo to your own number. Wait up to a minute."
    },
    {
      "step": "If it still fails: Confirm Messages app permissions",
      "why": "The app must have access to your media and SMS to send MMS.",
      "android_path": "Settings > Apps > Messages (or Samsung Messages) > Permissions",
      "permissions_to_allow": [
        "Photos and videos (or Files and media/Storage) = Allow",
        "SMS = Allow",
        "Optional: Camera = Allow (helps if you attach photos directly)"
      ],
      "then": "Return to Messages and try sending the photo to yourself again (Wi‑Fi still OFF)."
    },
    {
      "step": "If it still fails: Reset APN to default, then reboot",
      "why": "Ensures the MMSC (MMS server) and other data settings are correct for roaming.",
      "android_path": "Settings > Network & Internet (or Connections) > Mobile Network > Access Point Names",
      "actions": [
        "Tap the menu (⋮) > Reset to default (or Reset APNs). Confirm.",
        "Restart your phone: hold power > Restart.",
        "After restart, keep Wi‑Fi OFF and wait 30–60 seconds for 4G/5G to appear.",
        "Try sending the photo to yourself again."
      ]
    }
  ],
  "keep_in_mind": [
    "Ensure Data Roaming is still ON.",
    "Ensure Data Saver is OFF: Settings > Network & Internet > Data Saver > OFF.",
    "If you see a ‘key’ icon (VPN), disconnect it: Settings > Network & Internet > VPN > Disconnect."
  ],
  "what_to_report_back": [
    "Does a regular website load in your browser with Wi‑Fi OFF?",
    "After each step above, did the MMS to yourself send, or still fail?",
    "What brand/model is your phone (Samsung, Google Pixel, Motorola, etc.)? If any menus look different, tell me what you see so I can tailor the taps."
  ]
}

