messages.content:
{
  "short_answer": "Yes—please enable both Mobile Data and Data Roaming. But because you’re seeing “No Signal,” let’s also re-register your phone on the local network first.",
  "my_thought_process": "Your line is active, roaming is enabled on our side, and we added 2 GB. The “No Signal” means the phone isn’t registered to a local network in France yet. Enabling Data Roaming and Mobile Data is required for roaming data, but we also need to make sure the phone successfully attaches to a network.",
  "steps_now": [
    {
      "step": "Toggle Airplane Mode again",
      "how": "Turn Airplane Mode ON for ~10 seconds, then OFF.",
      "why": "Forces a fresh network registration, which often restores signal after travel."
    },
    {
      "step": "Check SIM status",
      "how": "Run the check_sim_status diagnostic on your phone.",
      "what_to_share": "Tell me if it says Active, Missing, or Locked.",
      "why": "If the SIM is missing/locked, the phone can’t connect to any network."
    },
    {
      "step": "Set network mode",
      "how": "Run check_network_mode_preference; if it’s 2G/3G, change it to set_network_mode_preference = \"4g_5g_preferred\".",
      "why": "Ensures the device can connect to modern networks abroad."
    },
    {
      "step": "Enable Data Roaming and Mobile Data",
      "how": "Turn Data Roaming ON (toggle_roaming) and Mobile Data ON (toggle_data).",
      "why": "Required for data while abroad; MMS needs mobile data."
    },
    {
      "step": "Wait up to 2 minutes",
      "how": "Watch the status bar for bars and a 4G/5G/LTE indicator.",
      "why": "It can take a bit for the device to attach to a partner network."
    },
    {
      "step": "Verify connection",
      "how": "Run check_network_status and share: signal strength, network type, mobile data status, and roaming status.",
      "why": "Confirms registration and data readiness."
    },
    {
      "step": "Test data and MMS",
      "how": "Turn Wi‑Fi OFF temporarily, open a webpage to confirm data, then resend the MMS.",
      "why": "Confirms mobile data is active and MMS will go through."
    }
  ],
  "if_no_signal_after_steps": [
    "Reboot the phone (reboot_device), wait 1–2 minutes after it powers back on.",
    "If still no signal, reseat the SIM (reseat_sim_card), then repeat the steps above.",
    "If check_sim_status shows Locked, tell me—SIM security needs specialized help."
  ],
  "questions": [
    "Can you tell me your phone type (Android or iPhone) so I can tailor any taps?",
    "After steps 1–4, what does check_network_status show (signal strength, network type, data enabled, roaming enabled)?"
  ]
}

