messages.content:
{
  "my_thought_process": "Your phone reports No SIM card detected, which prevents any network registration. Since your line is active and roaming is enabled on our side, the immediate goal is to get the SIM recognized. The standard fix is to reseat the SIM, then confirm the SIM shows Active and proceed with roaming/data setup.",
  "actions_to_take_now": [
    {
      "step": "Reseat the SIM card (on your device)",
      "how": "Use the reseat_sim_card action on your phone. If doing it physically: power off the phone, eject the SIM tray, remove the SIM, gently wipe it, reinsert it aligned correctly, and put the tray back. Then power the phone on.",
      "why": "Fixes most cases where the device momentarily loses contact with the SIM."
    },
    {
      "step": "Check SIM status again",
      "how": "Run check_sim_status.",
      "expected": "It should show Active. If Active, continue below."
    }
  ],
  "after_sim_detected_next_steps": [
    {
      "step": "Enable Data Roaming",
      "how": "Turn Data Roaming ON (toggle_roaming).",
      "why": "You’re in France; roaming must be on for data."
    },
    {
      "step": "Enable Mobile Data",
      "how": "Turn Mobile Data ON (toggle_data)."
    },
    {
      "step": "Wait 30–60 seconds for signal",
      "how": "Watch for bars and a 4G/5G/LTE indicator.",
      "why": "Allows the phone to attach to a local network."
    },
    {
      "step": "Verify connection",
      "how": "Run check_network_status and share the results (signal strength, network type, data enabled, roaming enabled)."
    },
    {
      "step": "Test data and MMS",
      "how": "Temporarily turn Wi‑Fi OFF, open a webpage to confirm data works, then resend the MMS."
    }
  ],
  "if_still_no_sim_after_reseat": [
    {
      "step": "Reboot the device",
      "how": "Use reboot_device, then check check_sim_status again."
    },
    {
      "step": "Try reseat one more time",
      "how": "Use reseat_sim_card again. If you have a physical SIM, ensure the tray/SIM aren’t damaged and the SIM’s gold contacts face the correct direction."
    },
    {
      "step": "If it still shows Missing",
      "how": "Tell me. This could indicate a hardware SIM reader issue or an eSIM profile issue. I’ll escalate to a human agent if needed after we confirm these steps."
    }
  ],
  "info_request": "Are you on Android or iPhone? I can provide exact taps for your model.",
  "ask_to_report_back": "Please reseat the SIM now and tell me what check_sim_status shows (Active, Missing, or Locked). If it becomes Active, also share the results of check_network_status after you enable Data Roaming and Mobile Data."
}

