      "why": "MMS needs any working mobile data. This verifies data is actually passing."
    },
    {
      "step": "Check Wi‑Fi Calling",
      "instructions": [
        "Run check_wifi_calling_status.",
        "If it’s ON, toggle_wifi_calling to turn it OFF for this test."
      ],
      "why": "Some configurations/carriers don’t support MMS over Wi‑Fi Calling while roaming."
    },
    {
      "step": "Check for VPN",
      "instructions": [
        "Run check_vpn_status.",
        "If a VPN is active, disconnect_vpn."
      ],
      "why": "VPNs can block or slow MMS connections."
    },
