messages.content:
{
  "message": "Good news: your connection looks excellent now, so your phone and photos are safe. Since calls/data work but MMS fails, the remaining likely causes are APN/MMSC settings, Wi‑Fi Calling, Data Saver/VPN, or the messaging app’s permissions. Let’s fix these step by step.",
  "thought_process": "MMS needs mobile data plus a correct MMSC URL in the APN. Wi‑Fi Calling can sometimes interfere while abroad, and Data Saver/VPN can also block MMS. Finally, the messaging app must have Storage and SMS permissions.",
  "steps_now": [
    {
      "step": "Quick MMS diagnostic",
      "how": "Run can_send_mms and tell me exactly what it reports.",
      "why": "Gives us a direct hint if the phone/app sees a configuration issue."
    },
    {
      "step": "Check APN/MMSC settings",
      "how": "Run check_apn_settings and share the result, especially the MMSC URL.",
      "why": "A missing/incorrect MMSC will block picture messages."
    },
    {
      "step": "If APN/MMSC looks wrong or missing: reset APN",
      "how": "Use reset_apn_settings, then reboot_device. After the reboot, try sending an MMS again.",
      "why": "Resetting restores the correct defaults for data and MMS."
    },
    {
      "step": "Turn OFF Wi‑Fi Calling (temporarily)",
      "how": "Run check_wifi_calling_status. If it’s ON, use toggle_wifi_calling to turn it OFF. Then try sending an MMS again.",
      "why": "Wi‑Fi Calling can sometimes interfere with MMS while roaming."
    },
    {
      "step": "Check Data Saver",
      "how": "Run check_data_restriction_status. If Data Saver is ON, use toggle_data_saver_mode to turn it OFF. Then try MMS.",
      "why": "Data Saver can restrict background data needed for MMS."
    },
    {
      "step": "Check for VPN",
      "how": "Run check_vpn_status. If a VPN is connected, use disconnect_vpn. Then try MMS again.",
      "why": "VPNs can block or slow MMS traffic, especially when roaming."
    },
    {
      "step": "Confirm messaging app permissions",
      "how": "Tell me which messaging app you’re using. Then run check_app_permissions for that app. If Storage (Photos/Media) or SMS permissions are missing, grant them with grant_app_permission for \"storage\" and \"sms\".",
      "why": "The app must be allowed to access media and send messages for MMS to work."
    }
  ],
  "reassurance": "None of these steps will harm your phone or your photos. Resetting APN and changing calling/permission settings is safe and reversible.",
  "then_test": "After each step, try sending a small photo to yourself or a family member. If it fails, note any exact error message you see.",
  "please_reply_with": [
    "Result of can_send_mms.",
    "The APN/MMSC details from check_apn_settings, or confirmation that you reset APN and rebooted.",
    "Wi‑Fi Calling status (and if you turned it OFF).",
    "Data Saver status.",
    "VPN status (and if disconnected).",
    "Which messaging app you use, and its permissions (whether Storage and SMS are allowed).",
    "If MMS sends successfully after any step, and any exact error message if it doesn’t."
  ]
}

