messages.content:
{
  "thought_process": "Great—your SIM is now detected, but the phone is on 2G with poor signal. Per our guidelines, MMS generally won’t work on 2G. The goal is to register on a 4G/5G network in France and then verify MMS. We’ll first change your network mode, then force the phone to latch onto a partner network, and finally reset APN if needed.",
  "steps_on_your_phone": [
    {
      "step": "Set preferred network to 4G/5G",
      "why": "Ensures the phone will use modern networks suitable for MMS.",
      "android_path": "Settings > Network & Internet (or Connections) > Mobile network > Preferred network type",
      "action": "Select 5G/4G/3G/2G (Auto) or 5G/4G preferred. Avoid 2G/3G-only modes."
    },
    {
      "step": "Network selection",
      "why": "If automatic selection keeps you on 2G, manually attach to a partner network.",
      "android_path": "Settings > Network & Internet > Mobile network > Network operators",
      "actions": [
        "Turn Select automatically ON and wait 1–2 minutes.",
        "If you still see 2G or no improvement: turn Select automatically OFF, tap Search networks.",
        "When the list appears, try each network in turn: Orange F, SFR, Bouygues Telecom, Free Mobile.",
        "After selecting one, wait up to 2 minutes and check if it shows 4G/LTE and at least a few bars."
      ]
