    {
      "step": "Turn OFF Wi‑Fi Calling (temporarily)",
      "why": "Removes a possible interference while roaming.",
      "android_path": "Settings > Network & Internet (or Connections) > Mobile network > Wi‑Fi Calling",
      "action": "Toggle Wi‑Fi Calling OFF for now."
    },
    {
      "step": "Reset APN to defaults (if still failing after getting 4G)",
      "why": "Fixes incorrect MMSC/APN that blocks MMS.",
      "android_path": "Settings > Network & Internet > Mobile network > Access Point Names",
      "action": "Open the menu (⋮) > Reset to default, then restart the phone. After reboot, confirm Mobile Data and Data Roaming are ON."
    }
  ],
  "tests_after_each_change": [
    "With Wi‑Fi OFF, try loading example.com in the browser.",
    "If the page loads, send a small photo via MMS and confirm whether it sends."
  ],
  "reminders": [
    "Keep Mobile Data and Data Roaming ON throughout.",
    "Give the phone 1–2 minutes after each network/operator change to register."
  ],
  "what_to_report_back": [
    "After setting the network mode and trying operator selection, what network type shows now (4G/LTE/5G/3G/2G) and how many bars?",
    "Were you able to attach to Orange, SFR, Bouygues, or Free—and which one gave you 4G/LTE?",
    "After resetting APN and rebooting (only if needed), does example.com load and does the MMS send?"
  ],
  "next_steps_if_still_stuck": "If you cannot get anything above 2G on any listed operator, tell me which operators you tried and what errors you saw. We’ll continue with targeted checks or escalate if necessary."
}

