      "step": "Reset APN to defaults, then reboot",
      "why": "An incorrect or missing MMSC URL in the APN will block MMS even if regular data works.",
      "android_path": "Settings > Network & Internet (or Connections) > Mobile network > Access Point Names",
      "action": "Open the menu (⋮) > Reset to default.",
      "after": [
        "Restart the phone completely.",
        "After reboot, ensure Mobile Data and Data Roaming are ON.",
        "Wait 1–2 minutes for registration, keep Wi‑Fi OFF, then try sending an MMS again."
      ]
    },
    {
      "step": "Confirm Data Saver is OFF",
      "why": "Data Saver can restrict background data that MMS needs.",
      "android_path": "Settings > Network & Internet > Data Saver",
      "action": "Make sure Data Saver is OFF."
    },
    {
      "step": "Ensure no VPN is active",
      "why": "VPNs can interfere with MMS routing while roaming.",
      "android_path": "Settings > Network & Internet > VPN",
      "action": "If any VPN shows as Connected, disconnect it and test MMS again."
