messages.content:
{
  "acknowledgment": "Great progress—your data and signal look excellent now, so MMS failing points to a phone-side configuration. We’ll verify the messaging app setup and the MMS server (MMSC) in the APN.",
  "thought_process": "MMS needs: working mobile data (you have it), correct APN with a valid MMSC, no app restrictions, and the correct default SMS/MMS app with SMS permission. We already reset APN and rebooted, turned Wi‑Fi Calling off, and confirmed Data Saver/VPN aren’t interfering. Next we’ll double‑check the default app/permissions and explicitly confirm the MMSC field isn’t blank. We’ll also run the device’s MMS diagnostic.",
  "steps_on_your_phone": [
    {
      "step": "Make sure your default SMS app is your Messages app",
      "path": "Settings > Apps > Default apps > SMS app",
      "action": "Select your default Messages app as the SMS app."
    },
    {
      "step": "Confirm the Messages app has SMS permission and unrestricted data",
      "path": "Settings > Apps > Messages (your default app) > Permissions",
      "actions": [
        "Ensure SMS permission is Allowed (in addition to Storage/Photos).",
        "Go back to Messages > Mobile data & Wi‑Fi (or Data usage) and turn ON Background data and Unrestricted data usage."
      ]
    },
    {
      "step": "Verify your active APN shows an MMSC value",
      "path": "Settings > Network & Internet (or Connections) > Mobile network > Access Point Names",
      "actions": [
        "Tap the APN that’s selected (the one with the filled radio dot).",
        "Check that the MMSC field is NOT blank.",
        "If it is blank or looks wrong: tap the menu (⋮) > Reset to default again, then ensure one APN is actually selected (radio dot filled), and reboot the phone once more."
      ]
    }
  ],
  "diagnostics_to_run": [
    {
      "tool": "can_send_mms()",
      "purpose": "This will tell us if the messaging app can send MMS given current settings.",
      "instruction": "Please run it and share the result."
    },
    {
      "tool": "check_apn_settings()",
      "purpose": "To confirm the APN name and that MMSC is populated after the reset.",
      "instruction": "Please run it and share what it shows for APN name and MMSC."
    }
  ],
  "test_after_steps": [
    "Keep Wi‑Fi OFF.",
    "Open your browser and confirm example.com loads.",
    "Then send a small photo via MMS to yourself or a contact and note what happens."
  ],
  "what_to_report_back": [
    "Is Messages set as the default SMS app?",
    "Is the SMS permission Allowed for the Messages app, and are Background data and Unrestricted data enabled?",
    "From check_apn_settings(): what APN name is shown, and is the MMSC field populated?",
    "From can_send_mms(): what result did you get?",
    "After these checks, does the MMS still say “Not sent,” or did it go through?"
  ],
  "note_on_next_steps": "If the MMSC field is blank even after resetting APN and rebooting, that’s likely the cause. I can escalate to a human agent to provision the correct APN/MMSC details for your device. Otherwise, share the diagnostics results and we’ll continue from there."
}

