{
  "status": "proceed_wifi_calling_off",
  "thought_process": "You have strong 5G data and APN/MMSC was reset, so base connectivity and MMS server settings should be in place. The most common remaining causes are Wi‑Fi Calling interference, missing messaging app permissions, Data Saver restrictions, or an active VPN.",
  "steps_now_in_order": [
    "Turn OFF Wi‑Fi Calling, then test sending an MMS to yourself.",
    "If still failing, ensure the messaging app has required permissions (Storage/Photos and SMS), and allow unrestricted/background data for the app. Also ensure Data Saver is OFF.",
    "If still failing, make sure no VPN is connected (disconnect it), then test again."
  ],
  "how_to_do_it": {
    "turn_off_wifi_calling": {
      "iPhone": [
        "Settings > Cellular > Wi‑Fi Calling > toggle OFF."
      ],
      "Android": [
        "Settings > Network & Internet (or Connections) > Mobile network (or SIM settings) > Wi‑Fi Calling > toggle OFF."
      ],
      "test_after": [
        "Keep Wi‑Fi OFF, Mobile Data ON, Data Roaming ON.",
        "Send an MMS to your own number and report what happens (sends, stuck on sending, or fails)."
      ]
    },
    "check_app_permissions_and_data": {
      "iPhone": [
        "Settings > Privacy & Security > Photos > select your messaging app > allow access (e.g., All Photos or Selected Photos).",
        "If sending video/voice, also check Camera and Microphone.",
        "Data Saver equivalent isn’t typical on iPhone, so no change needed there."
      ],
      "Android": [
        "Settings > Apps > [Your Messaging App] > Permissions > allow Storage (or Photos and videos/Media) and SMS.",
        "Settings > Apps > [Your Messaging App] > Mobile data & Wi‑Fi > enable Background data and Unrestricted data usage.",
        "Settings > Network & Internet (or Connections) > Data Saver > ensure OFF."
      ],
      "test_after": [
        "With Wi‑Fi OFF and data ON, send an MMS to yourself again."
      ]
    },
    "vpn_check": {
      "iPhone": [
        "Settings > VPN (or Settings > General > VPN & Device Management) > ensure Not Connected."
      ],
      "Android": [
        "Settings > Network & Internet > VPN > Disconnect any active VPN."
      ],
      "test_after": [
        "Try sending an MMS to yourself again."
      ]
    }
  },
  "optional_diagnostic": [
    "If your phone offers a built-in ‘Can send MMS’ diagnostic, run it and share the result."
  ],
  "next_actions_waiting_on_you": [
    "Please turn OFF Wi‑Fi Calling now and test sending an MMS to yourself.",
    "If it still fails, adjust app permissions and data settings as above and test again.",
    "If it still fails, ensure no VPN is connected and test again.",
    "Share the results after each step, including any on-screen message (e.g., sending…, failed) and confirm your status bar still shows 5G with data arrows."
  ],
  "reminders": [
    "Roaming is enabled on your line and you have 2 GB of refueled data active.",
    "Stay on 4G/5G preferred while testing."
  ]
}

