messages.content:
{
  "status": "action_required_on_device",
  "thought_process": "You have strong 5G data, roaming ON, APN/MMSC reset, and Wi‑Fi Calling OFF. The remaining likely blocker is the messaging app lacking media access. MMS needs the app to access photos/videos (storage/media). We’ll grant that permission and ensure no app-level data restrictions.",
  "what_to_do_next": [
    "Step 1 — Check app permissions:",
    "If your phone supports device diagnostics, run: check_app_permissions(app_name=\"messaging\") and share the result.",
    "Otherwise use the menu steps below for your platform."
  ],
  "how_to_grant_permissions": {
    "Android": [
      "Settings > Apps > [Your Messaging App] > Permissions.",
      "Look for and Allow: “Photos and videos” (or “Media” or “Files and media”, varies by Android version).",
      "Ensure SMS is Allowed (you already have this)."
    ],
    "iPhone": [
      "Settings > Privacy & Security > Photos > [Your messaging app] > set to All Photos (or Selected Photos with at least one test image).",
      "If you plan to send videos/voice notes, also check Camera and Microphone permissions in Settings > Privacy & Security."
    ]
  },
  "remove_app_data_restrictions": {
    "Android": [
      "Settings > Apps > [Your Messaging App] > Mobile data & Wi‑Fi > turn ON Background data and Unrestricted data usage.",
      "Settings > Network & Internet (or Connections) > Data Saver > ensure OFF (you already confirmed OFF)."
    ],
    "iPhone": [
      "No additional system Data Saver step typically needed."
    ]
  },
  "optional_device_tests": [
    "Run: can_send_mms() and tell me the result."
  ],
  "test_after_changes": [
    "Keep Wi‑Fi OFF, Mobile Data ON, Data Roaming ON.",
    "Open the messaging app and send a small photo MMS to your own number.",
    "Tell me what happens (sends successfully, stays on “sending…”, or fails)."
  ],
  "if_permissions_not_listed": [
    "On Android, some versions group this under “Photos and videos” instead of “Storage.” If you still can’t find it, check Settings > Privacy > Permission manager > Photos and videos > locate your messaging app and set to Allow.",
    "On iPhone, ensure your messaging app appears under Settings > Privacy & Security > Photos. If it doesn’t, try attaching a photo from within the app once—iOS may prompt for permission. If prompted, choose Allow."
  ],
  "next_actions_waiting_on_you": [
    "Grant the Photos/Media (storage) permission to your messaging app as above.",
    "Enable background/unrestricted data for the app (Android).",
    "Run the MMS-to-self test and share the result or the can_send_mms() diagnostic output."
  ]
}

